 @GetMapping("/salaries") public List<Map<String,Object>> salaries(@RequestParam String month){var m=month(month);return jdbc.queryForList("SELECT d.id,d.code,d.name,d.warehouse_id,coalesce(r.monthly_amount,15000000) AS monthly_salary FROM drivers d LEFT JOIN LATERAL(SELECT monthly_amount FROM driver_salary_rates WHERE driver_id=d.id AND effective_month<=? ORDER BY effective_month DESC LIMIT 1)r ON true ORDER BY d.code",m.atDay(1));}
 @PostMapping("/salaries") @Transactional public Map<String,Object> setSalary(@RequestBody Map<String,Object>b,HttpServletRequest req){long uid=admin(req);return once("salary-rate",b,uid,()->{int driver=Math.toIntExact(whole(b,"driverId",1,Integer.MAX_VALUE));var m=month(text(b,"month",7,7));long amount=whole(b,"amount",0,1000000000);String reason=text(b,"reason",3,400);jdbc.queryForMap("SELECT id FROM drivers WHERE id=? FOR UPDATE",driver);if(jdbc.queryForObject("SELECT count(*) FROM driver_payrolls WHERE driver_id=? AND period>=? AND status='approved'",Integer.class,driver,m.atDay(1))>0)conflict("Tháng đã có lương được duyệt; hủy phiếu trước khi đổi mức lương");jdbc.update("INSERT INTO driver_salary_rates(driver_id,effective_month,monthly_amount,created_by) VALUES(?,?,?,?) ON CONFLICT(driver_id,effective_month) DO UPDATE SET monthly_amount=excluded.monthly_amount,created_by=excluded.created_by,created_at=now()",driver,m.atDay(1),amount,uid);return Map.of("saved",true,"monthly_salary",amount);});}
